with base as (select * from subscriptions where plan = 'basic'), subscriptions_stats as (select date_format(start_date, 'yyyy-MM') as start_month, case when monthly_fee >= 225 then 'high' when monthly_fee >= 52 then 'mid' else 'low' end as monthly_fee_bucket, count(*) as cnt from base group by date_format(start_date, 'yyyy-MM'), case when monthly_fee >= 225 then 'high' when monthly_fee >= 52 then 'mid' else 'low' end) select start_month, monthly_fee_bucket, cnt from subscriptions_stats
